  crunch: { name: 'Crunch', pattern: 'core', region: 'upper', equipment: ['bw'], measure: 'reps', workType: 'reps', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 1, harder: 'situp', rx: { beg: '10-12 reps', int: '12-15 reps', adv: '15-20 reps' }, demoUrl: null, cues: 'Lie on back, knees bent. Curl the shoulder blades off the floor by flexing the abs — don\'t yank the neck. Lower with control. Top-ab spinal flexion.' },
