  lying_knee_tuck: { name: 'Lying Knee Tuck', pattern: 'core', region: 'lower', equipment: ['bw'], measure: 'reps', workType: 'reps', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 1, harder: 'reversecrunch', rx: { beg: '10-12 reps', int: '12-15 reps', adv: '15-20 reps' }, demoUrl: null, cues: 'Lie on back, hands by hips or under the glutes. Draw the knees toward the chest, curling the hips slightly off the floor. Lower-ab entry movement.' },
  bear_hold: { name: 'Bear Hold', pattern: 'core', region: 'inner', equipment: ['bw'], measure: 'hold', workType: 'hold', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 2, main: true, easier: 'birddog', harder: 'bearholdtaps', rx: { beg: '20-30 sec', int: '30-40 sec', adv: '40-50 sec' }, demoUrl: null, cues: 'Bear-crawl position held still: hands under shoulders, knees hovering an inch off the floor, back flat. Squeeze everything and hold. A held bear crawl — brutal deep-core tension.' },
  bent_knee_hollow_hold: { name: 'Bent-Knee Hollow Hold', pattern: 'core', family: 'hollow', region: 'inner', equipment: ['bw'], measure: 'hold', workType: 'hold', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 2, easier: 'deadbug', harder: 'hollowbodyhold', rx: { beg: '20-30 sec', int: '30-40 sec', adv: '40-50 sec' }, demoUrl: null, cues: 'Lift the shoulder blades off the floor, knees bent at 90°, arms extended straight back behind the ears. Low back pressed flat. The easier hollow — keeps the legs light to protect the lower back.' },
  bird_dog: { name: 'Bird Dog', pattern: 'core', region: 'inner', equipment: ['bw'], measure: 'reps', workType: 'reps', load: 'bw', laterality: 'unilateral', level: 'beg', diff: 2, main: true, noPR: true, harder: 'bearhold', rx: { beg: '10-12 reps', int: '12-15 reps', adv: '15-20 reps' }, demoUrl: null, cues: 'On all fours. Extend the right arm forward and the left leg straight back at the same time. Hold 2 sec without letting the hips rotate, then switch sides. Anti-rotation control.' },
