  flutter_kicks: { name: 'Flutter Kicks', pattern: 'core', region: 'lower', equipment: ['bw'], measure: 'reps', workType: 'reps', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 2, easier: 'lyingkneetuck', harder: 'scissorkicks', rx: { beg: '10-12 reps', int: '12-15 reps', adv: '15-20 reps' }, demoUrl: null, cues: 'Legs straight, heels six inches off the floor, low back pressed down. Alternate small fast up-down kicks. Keep the core braced the whole set.' },
  foot_supported_l_sit: { name: 'Foot-Supported L-Sit', pattern: 'core', region: 'inner', equipment: ['bw'], measure: 'hold', workType: 'hold', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 2, harder: 'alternatingsingleleglsit', rx: { beg: '20-30 sec', int: '30-40 sec', adv: '40-50 sec' }, demoUrl: null, cues: 'Beginner L-sit: hands pressing down on the floor (or parallettes), knees bent or heels lightly touching the floor. Press the shoulders down and lift the chest. Build the compression before going feet-up.' },
  reverse_crunch: { name: 'Reverse Crunch', pattern: 'core', region: 'lower', equipment: ['bw'], measure: 'reps', workType: 'reps', load: 'bw', laterality: 'bilateral', level: 'beg', diff: 2, easier: 'lyingkneetuck', harder: 'lyinglegraise', rx: { beg: '10-12 reps', int: '12-15 reps', adv: '15-20 reps' }, demoUrl: null, cues: 'Knees at 90°. Curl the pelvis up toward the ribs — lift the hips off the floor using the lower abs, not a leg swing. Slow eccentric.' },
