  /* ---------- KETTLEBELL ------------------------------------------------
     Added 2026-08-12. These came out of building Ozzy's program: he owns a
     kettlebell, a bench and a mat, and the library had almost no kettlebell
     movement in it at all. Written against the invariant — a program cannot
     prescribe a movement the database does not hold.

     The coaching copy (why it matters, the cues, the mistake everyone makes)
     lives in the spine, assembled by tools/build-spine.mjs. What is here is
     the movement itself. */
  kb_deadlift: { name: 'Kettlebell Deadlift', pattern: 'hinge', family: 'hinge', equipment: ['kb'], measure: 'reps', workType: 'reps', load: 'weighted', laterality: 'bilateral', level: 'beg', diff: 2, harder: 'kb_swing', demoUrl: null, cues: 'Bell on the floor between the feet. Push the hips back until your hands reach it, back flat, shins near vertical. Stand by driving the floor away.' },
  kb_rdl: { name: 'Kettlebell Romanian Deadlift', pattern: 'hinge', family: 'hinge', equipment: ['kb'], measure: 'reps', workType: 'reps', load: 'weighted', laterality: 'bilateral', level: 'beg', diff: 3, easier: 'kb_deadlift', harder: 'single_leg_rdl', demoUrl: null, cues: 'Start standing. Push the hips back and slide the bell down the thighs, knees soft and staying soft. Go until the hamstrings stop you.' },
  kb_floor_press: { name: 'Kettlebell Floor Press', pattern: 'push', family: 'press', equipment: ['kb', 'mat'], measure: 'reps', workType: 'reps', load: 'weighted', laterality: 'unilateral', level: 'beg', diff: 3, demoUrl: null, cues: 'On your back, knees bent, bell in one hand at the chest. Press to over the shoulder, not over the face. The floor stops the elbow — touch, pause, press.' },
  kb_press: { name: 'Kettlebell Overhead Press', pattern: 'press', family: 'press', equipment: ['kb'], measure: 'reps', workType: 'reps', load: 'weighted', laterality: 'unilateral', level: 'int', diff: 5, easier: 'kb_floor_press', demoUrl: null, cues: 'Bell racked on the forearm, wrist straight. Press up and slightly back until the arm is by the ear. Ribs down; the lower back does not help.' },
