/* Gym / machine movements (second user). Tagged `gymOnly` at merge time so a
   profile without `gymLibrary: true` never sees them in swap or add lists —
   equipment tags alone weren't enough, since some of these are plain dumbbell
   and barbell moves that a bodyweight profile technically "has". */
for (const [id, m] of Object.entries(GYM_EXERCISES)) EXERCISES[id] = { ...m, gymOnly: true };
